using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using Xunit;

namespace Nops.Core.Tests;

/// <summary>
/// End-to-end integration tests: decrypt the committed SOPS fixtures (generated by the
/// real `sops` CLI) with the TEST-ONLY age key and verify both the values and the MAC.
/// </summary>
public class SopsFileIntegrationTests
{
    private static readonly string FixtureDir = Path.Combine(
        AppContext.BaseDirectory, "Fixtures");

    private static readonly string AgeSecretKey = LoadAgeSecretKey();

    private static string LoadAgeSecretKey()
    {
        var keys = LoadAllAgeSecretKeys();
        if (keys.Count == 0)
            throw new InvalidOperationException("AGE-TEST-KEY.txt does not contain an AGE-SECRET-KEY line");
        return keys[0];
    }

    private static List<string> LoadAllAgeSecretKeys()
    {
        var keyFile = Path.Combine(FixtureDir, "AGE-TEST-KEY.txt");
        return File.ReadAllLines(keyFile)
            .Where(l => l.StartsWith("AGE-SECRET-KEY-", StringComparison.Ordinal))
            .Select(l => l.Trim())
            .ToList();
    }

    private static SopsOptions Options(params string[] keys) =>
        new SopsOptions { AgeIdentities = keys.Length == 0 ? new[] { AgeSecretKey } : keys };

    private static byte[] ReadFixture(string name) => File.ReadAllBytes(Path.Combine(FixtureDir, name));

    [Fact]
    public async Task SecretsYaml_DecryptsAndVerifiesMac()
    {
        var dict = await SopsFile.DecryptToDictionaryAsync(ReadFixture("secrets.sops.yaml"), "yaml", Options());

        Assert.Equal("hello world", dict["myapp1"]);
        Assert.Equal("admin", dict["app2:db:user"]);
        Assert.Equal("s3cret!", dict["app2:db:password"]);
        Assert.Equal("api-key-12345", dict["app2:key"]);
        Assert.Equal("3.14", dict["number"]);
        Assert.Equal("True", dict["somebooleans:0"]);
        Assert.Equal("False", dict["somebooleans:1"]);
        Assert.Equal("deep-secret", dict["this:is:a:nested:value"]);
        Assert.Equal("public data 1", dict["somelist_unencrypted:0"]);
        Assert.Equal("public data 2", dict["somelist_unencrypted:1"]);
        Assert.Equal("all public", dict["nested_unencrypted:this:is"]);
    }

    [Fact]
    public async Task NestedYaml_DecryptsAndVerifiesMac()
    {
        var dict = await SopsFile.DecryptToDictionaryAsync(ReadFixture("nested.sops.yaml"), "yaml", Options());

        Assert.Equal("deep-value-42", dict["level1:level2:level3:level4:secret"]);
        Assert.Equal("first", dict["array_of_secrets:0"]);
        Assert.Equal("second", dict["array_of_secrets:1"]);
        Assert.Equal("third", dict["array_of_secrets:2"]);
        Assert.Equal("hidden", dict["mixed:encrypted"]);
        Assert.Equal("visible", dict["mixed:unencrypted_public"]);
    }

    [Fact]
    public async Task MultiKeygroupYaml_DecryptsAndVerifiesMac_WithTwoOfThreeShares()
    {
        // Real 2-of-3 Shamir secret sharing: key A and key B must combine.
        var keys = LoadAllAgeSecretKeys();
        Assert.True(keys.Count >= 2, "multi-keygroup fixture requires at least two test identities");

        var dict = await SopsFile.DecryptToDictionaryAsync(
            ReadFixture("multi-keygroup.sops.yaml"), "yaml", Options(keys[0], keys[1]));

        Assert.Equal("localhost", dict["database:host"]);
        Assert.Equal("5432", dict["database:port"]);
        Assert.Equal("super-secret-password", dict["database:password"]);
        Assert.Equal("my-api-key-12345", dict["api_key"]);
    }

    [Fact]
    public async Task MultiKeygroupYaml_InsufficientShares_Throws()
    {
        // Only one of the three Shamir shares is available → cannot reach threshold 2.
        var keys = LoadAllAgeSecretKeys();
        await Assert.ThrowsAnyAsync<Exception>(() =>
            SopsFile.DecryptToDictionaryAsync(
                ReadFixture("multi-keygroup.sops.yaml"), "yaml", Options(keys[0])));
    }

    [Fact]
    public async Task UnencryptedTypesYaml_DecryptsAndVerifiesMac()
    {
        var dict = await SopsFile.DecryptToDictionaryAsync(
            ReadFixture("unencrypted-types.sops.yaml"), "yaml", Options());

        // Plain scalars are typed exactly like gopkg.in/yaml.v3.
        Assert.Equal("True", dict["bool_true_unencrypted"]);
        Assert.Equal("False", dict["bool_false_unencrypted"]);
        Assert.Equal("42", dict["int_unencrypted"]);
        Assert.Equal("-7", dict["neg_int_unencrypted"]);
        Assert.Equal("16", dict["hex_unencrypted"]);
        Assert.Equal("8", dict["octal_unencrypted"]);
        Assert.Equal("1", dict["float_whole_unencrypted"]);
        Assert.Equal("3.14", dict["float_unencrypted"]);
        Assert.Equal("1000", dict["exponent_unencrypted"]);
        Assert.Equal("2024-01-02T00:00:00Z", dict["date_unencrypted"]);
        Assert.Equal("2024-01-01T10:20:30Z", dict["datetime_unencrypted"]);
        Assert.Equal("2024-01-01T10:20:30Z", dict["space_datetime_unencrypted"]);
        // A "T"-separated timestamp without a timezone is NOT resolved by yaml.v3.
        Assert.Equal("2024-01-01T10:20:30", dict["no_tz_datetime_unencrypted"]);
        Assert.Equal("true", dict["quoted_bool_unencrypted"]);
        Assert.Equal("hello", dict["string_unencrypted"]);
        Assert.Equal("super-secret-value", dict["secret"]);

        // null / ~ values are not emitted.
        Assert.False(dict.ContainsKey("null_unencrypted"));
        Assert.False(dict.ContainsKey("tilde_unencrypted"));
    }

    [Fact]
    public async Task CommentsYaml_DecryptsAndVerifiesMac_WithCommentRegex()
    {
        // encrypted_comment_regex = "^ sops_": values preceded by a matching comment
        // are encrypted; comments are captured but never contribute to the MAC.
        var dict = await SopsFile.DecryptToDictionaryAsync(
            ReadFixture("comments.sops.yaml"), "yaml", Options());

        Assert.Equal("hidden-data", dict["secret_value"]);
        Assert.Equal("visible", dict["public_value"]);
        Assert.Equal("also-hidden", dict["more_secret"]);
        Assert.Equal("more-hidden", dict["another_secret"]);
    }

    [Fact]
    public async Task CommentsYaml_CapturesComments()
    {
        var tree = await SopsFile.DecryptTreeAsync(
            ReadFixture("comments.sops.yaml"), "yaml", Options());

        var comments = tree.Branches[0]
            .Where(i => i.Key is Nops.Core.Stores.Comment)
            .Select(i => ((Nops.Core.Stores.Comment)i.Key).Value)
            .ToList();

        // The leading space is preserved: sops strips only the '#'.
        Assert.Contains(" sops_secret", comments);
        Assert.Contains(" public_comment", comments);
        Assert.Contains(" sops_secret2", comments);
    }

    [Fact]
    public async Task MacOnlyEncryptedYaml_DecryptsAndVerifiesMac()
    {
        var dict = await SopsFile.DecryptToDictionaryAsync(ReadFixture("mac-only-encrypted.sops.yaml"), "yaml", Options());

        Assert.Equal("should-be-encrypted", dict["secret_key"]);
        Assert.Equal("not-secret", dict["public_key"]);
        Assert.Equal("also-hidden", dict["another_secret"]);
    }

    [Fact]
    public async Task Dotenv_DecryptsAndVerifiesMac()
    {
        var dict = await SopsFile.DecryptToDictionaryAsync(ReadFixture("dotenv.sops.env"), "dotenv", Options());

        Assert.Equal("localhost", dict["DB_HOST"]);
        Assert.Equal("5432", dict["DB_PORT"]);
        Assert.Equal("supersecret", dict["DB_PASSWORD"]);
        Assert.Equal("abc123xyz", dict["API_KEY"]);
        Assert.Equal("not-secret", dict["PUBLIC_VAR"]);
    }

    [Fact]
    public async Task Ini_DecryptsAndVerifiesMac()
    {
        var dict = await SopsFile.DecryptToDictionaryAsync(ReadFixture("ini.sops.ini"), "ini", Options());

        Assert.Equal("localhost", dict["database:host"]);
        Assert.Equal("5432", dict["database:port"]);
        Assert.Equal("dbpass123", dict["database:password"]);
        Assert.Equal("api-key-secret", dict["api:key"]);
        Assert.Equal("https://api.example.com", dict["api:endpoint"]);
    }

    [Fact]
    public async Task Ini_DefaultSectionAndBackslashes_MatchSops()
    {
        var dict = await SopsFile.DecryptToDictionaryAsync(ReadFixture("ini-default-section.sops.ini"), "ini", Options());

        // Keys before the first [section] live in DEFAULT; values are not unescaped.
        Assert.Equal("top-secret", dict["DEFAULT:name"]);
        Assert.Equal(@"C:\new\dir", dict["DEFAULT:path_unencrypted"]);
        Assert.Equal("admin", dict["db:user"]);
        Assert.Equal(@"line1\nline2", dict["db:multi"]);
    }

    [Fact]
    public async Task Json_LargeNumbers_VerifyMac()
    {
        var dict = await SopsFile.DecryptToDictionaryAsync(ReadFixture("numbers.sops.json"), "json", Options());

        Assert.Equal("9007199254740993", dict["i64_unencrypted"]);
        Assert.Equal("s3", dict["secret"]);
    }

    [Fact]
    public async Task Binary_DecryptsAndVerifiesMac()
    {
        var tree = await SopsFile.DecryptTreeAsync(ReadFixture("binary.sops.json"), "binary", Options());

        var data = tree.Branches[0].First(i => i.Key?.ToString() == "data").Value;
        Assert.Equal("hello-binary-data", data);
    }

    [Fact]
    public async Task SecretsJson_DecryptsAndVerifiesMac()
    {
        var dict = await SopsFile.DecryptToDictionaryAsync(ReadFixture("secrets.sops.json"), "json", Options());

        Assert.Equal("localhost", dict["database:host"]);
        Assert.Equal("5432", dict["database:port"]);
        Assert.Equal("super-secret-password", dict["database:password"]);
        Assert.Equal("my-api-key-12345", dict["api_key"]);
        Assert.Equal("True", dict["debug"]);
    }

    [Fact]
    public async Task TypedBinding_PreservesTypes()
    {
        var settings = await SopsFile.DecryptAsync<SecretsSettings>(
            ReadFixture("secrets.sops.yaml"), "yaml", Options());

        Assert.Equal("hello world", settings.MyApp1);
        Assert.Equal(3.14, settings.Number);
        Assert.True(settings.SomeBooleans[0]);
        Assert.False(settings.SomeBooleans[1]);
    }

    [Fact]
    public async Task AnchorsYaml_ExpandsAliasesAndVerifiesMac()
    {
        var dict = await SopsFile.DecryptToDictionaryAsync(ReadFixture("anchors.sops.yaml"), "yaml", Options());

        Assert.Equal("db.local", dict["defaults_unencrypted:host"]);
        Assert.Equal("db.local", dict["prod_unencrypted:host"]);
        Assert.Equal("5432", dict["prod_unencrypted:port"]);
        Assert.Equal("hunter2", dict["password"]);
    }

    [Fact]
    public async Task FootCommentsYaml_AttachesCommentsLikeSops()
    {
        var dict = await SopsFile.DecryptToDictionaryAsync(ReadFixture("footcomments.sops.yaml"), "yaml", Options());

        // "# sops:enc" closes the nested "a" block but is the head comment of the next key.
        Assert.Equal("hello", dict["c_unencrypted"]);
        Assert.Equal("1", dict["a:b"]);
        // Comments inside a sequence do not shift element indices.
        Assert.Equal("a", dict["hosts_unencrypted:0"]);
        Assert.Equal("b", dict["hosts_unencrypted:1"]);
        Assert.False(dict.ContainsKey("hosts_unencrypted:2"));
        Assert.Equal("plain", dict["e"]);
    }

    private const string PgpTestFingerprint = "86498AF4273A49F7D96FF1A62C9F3DFF82C80F58";

    [Theory]
    [InlineData("")]
    [InlineData(PgpTestFingerprint)]
    public async Task PgpYaml_DecryptsWithEncryptionSubkey(string fingerprint)
    {
        // gpg encrypts to the [E] subkey, not the primary key the fingerprint names.
        var options = new SopsOptions
        {
            MasterKeys = new[] { new Nops.Core.Keys.PgpMasterKey(fingerprint, ReadFixture("PGP-TEST-KEY.asc")) },
        };

        var dict = await SopsFile.DecryptToDictionaryAsync(ReadFixture("pgp.sops.yaml"), "yaml", options);

        Assert.Equal("pgp-secret", dict["db_password"]);
        Assert.Equal("5432", dict["port_unencrypted"]);
    }

    [Fact]
    public async Task PgpYaml_WrongFingerprint_DoesNotDecrypt()
    {
        var options = new SopsOptions
        {
            MasterKeys = new[] { new Nops.Core.Keys.PgpMasterKey("0000000000000000000000000000000000000000", ReadFixture("PGP-TEST-KEY.asc")) },
        };

        await Assert.ThrowsAsync<InvalidOperationException>(() =>
            SopsFile.DecryptToDictionaryAsync(ReadFixture("pgp.sops.yaml"), "yaml", options));
    }

    [Fact]
    public async Task SpecialFloatsYaml_BindsTyped()
    {
        var settings = await SopsFile.DecryptAsync<SpecialFloats>(ReadFixture("special-floats.sops.yaml"), "yaml", Options());

        Assert.True(double.IsNaN(settings.Ratio));
        Assert.True(double.IsPositiveInfinity(settings.Max));
        Assert.True(double.IsNegativeInfinity(settings.Min));
        Assert.Equal("s", settings.Secret);
    }

    [Fact]
    public void Dotenv_FlattenRoundTrip_KeepsAllRecipientsAndOffset()
    {
        var loaded = Nops.Core.Stores.DotenvStore.LoadEncrypted(ReadFixture("dotenv.sops.env"), "dotenv.sops.env");
        var lastModified = new DateTimeOffset(2026, 10, 2, 18, 56, 18, TimeSpan.FromHours(2));
        var metadata = loaded.Metadata with
        {
            Age = new[]
            {
                new Nops.Core.Stores.AgeEntry("age1first", "enc-first"),
                new Nops.Core.Stores.AgeEntry("age1second", "enc-second"),
            },
            LastModified = lastModified,
        };
        var tree = new Nops.Core.Stores.SopsTree(loaded.Branches, metadata, loaded.FilePath);

        var text = Nops.Core.Stores.DotenvStore.FlattenToDotenv(tree);
        var reloaded = Nops.Core.Stores.DotenvStore.LoadEncrypted(Encoding.UTF8.GetBytes(text), "roundtrip.env");

        Assert.Equal(new[] { "age1first", "age1second" }, reloaded.Metadata.Age.Select(a => a.Recipient));
        Assert.Contains("sops_lastmodified=2026-10-02T18:56:18+02:00", text);
        Assert.Equal(lastModified, reloaded.Metadata.LastModified);
    }

    [Fact]
    public async Task TamperedMac_Throws()
    {
        // Tamper with a plaintext (unencrypted) value: no GCM is involved, so the
        // only failure mode is an exact MAC mismatch.
        var bytes = ReadFixture("secrets.sops.yaml");
        var text = Encoding.UTF8.GetString(bytes).Replace("public data 1", "public data X");
        var tampered = Encoding.UTF8.GetBytes(text);

        await Assert.ThrowsAsync<Nops.Core.Stores.MacMismatchException>(() =>
            SopsFile.DecryptToDictionaryAsync(tampered, "yaml", Options()));
    }

    public sealed class SpecialFloats
    {
        [System.Text.Json.Serialization.JsonPropertyName("ratio_unencrypted")]
        public double Ratio { get; set; }
        [System.Text.Json.Serialization.JsonPropertyName("max_unencrypted")]
        public double Max { get; set; }
        [System.Text.Json.Serialization.JsonPropertyName("min_unencrypted")]
        public double Min { get; set; }
        [System.Text.Json.Serialization.JsonPropertyName("secret")]
        public string? Secret { get; set; }
    }

    public sealed class SecretsSettings
    {
        [System.Text.Json.Serialization.JsonPropertyName("myapp1")]
        public string? MyApp1 { get; set; }
        [System.Text.Json.Serialization.JsonPropertyName("number")]
        public double Number { get; set; }
        [System.Text.Json.Serialization.JsonPropertyName("somebooleans")]
        public List<bool> SomeBooleans { get; set; } = new();
    }
}
